import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
experiment_data = np.load(
    os.path.join(working_dir, "experiment_data.npy"), allow_pickle=True
).item()

for dataset_name, data in experiment_data.items():
    print(f"=== Dataset: {dataset_name} ===")

    base_asr = data.get("base_asr")
    rr_asr = data.get("rr_asr")
    if base_asr is not None:
        print(f"{dataset_name} base overall Attack Success Rate (ASR): {base_asr:.4f}")
    if rr_asr is not None:
        print(f"{dataset_name} RR overall Attack Success Rate (ASR): {rr_asr:.4f}")
    if base_asr is not None and rr_asr is not None:
        print(f"{dataset_name} ASR delta (RR - base): {rr_asr - base_asr:+.4f}")

    base_by_attack = data.get("base_asr_by_attack", {}) or {}
    for style, val in base_by_attack.items():
        print(f"{dataset_name} base ASR by attack style [{style}]: {val:.4f}")

    rr_by_attack = data.get("rr_asr_by_attack", {}) or {}
    for style, val in rr_by_attack.items():
        print(f"{dataset_name} RR ASR by attack style [{style}]: {val:.4f}")

    benign_before = data.get("benign_before")
    benign_after = data.get("benign_after")
    if benign_before is not None:
        print(f"{dataset_name} benign generation (before RR training): {benign_before}")
    if benign_after is not None:
        print(f"{dataset_name} benign generation (after RR training): {benign_after}")

    probe = data.get("generalization_probe", {}) or {}
    if "pre_train_cos" in probe:
        print(
            f"{dataset_name} held-out harmful mean cos(lora,base) pre-training: "
            f"{probe['pre_train_cos']:.4f}"
        )
    if "post_train_cos" in probe:
        print(
            f"{dataset_name} held-out harmful mean cos(lora,base) post-training: "
            f"{probe['post_train_cos']:.4f}"
        )
    if "pre_train_cos" in probe and "post_train_cos" in probe:
        print(
            f"{dataset_name} held-out harmful cos delta (post - pre): "
            f"{probe['post_train_cos'] - probe['pre_train_cos']:+.4f}"
        )

    base_ci = data.get("base_ci")
    rr_ci = data.get("rr_ci")
    if base_ci is not None:
        print(
            f"{dataset_name} base ASR 95% bootstrap CI: "
            f"[{base_ci[0]:.4f}, {base_ci[1]:.4f}]"
        )
    if rr_ci is not None:
        print(
            f"{dataset_name} RR ASR 95% bootstrap CI: "
            f"[{rr_ci[0]:.4f}, {rr_ci[1]:.4f}]"
        )

    loss_log = data.get("loss_log", []) or []
    if len(loss_log) > 0:
        final = loss_log[-1]
        print(f"{dataset_name} final training total loss: {final.get('loss'):.4f}")
        print(
            f"{dataset_name} final training harmful representation loss: "
            f"{final.get('harm_loss'):.4f}"
        )
        print(
            f"{dataset_name} final training retain cross-entropy loss: "
            f"{final.get('retain_ce'):.4f}"
        )
        print(
            f"{dataset_name} final training retain representation-diff loss: "
            f"{final.get('rep_diff'):.4f}"
        )
        min_total = min(l["loss"] for l in loss_log)
        print(f"{dataset_name} best (min) training total loss: {min_total:.4f}")

    train_losses = data.get("losses", {}).get("train", []) or []
    if len(train_losses) > 0:
        print(
            f"{dataset_name} final logged training loss: {float(train_losses[-1]):.4f}"
        )
        print(
            f"{dataset_name} best (min) logged training loss: "
            f"{float(np.min(train_losses)):.4f}"
        )

    val_metrics = data.get("metrics", {}).get("val", []) or []
    if len(val_metrics) > 0:
        vm = val_metrics[-1]
        print(f"{dataset_name} validation summary - base ASR: {vm.get('base_asr'):.4f}")
        print(f"{dataset_name} validation summary - RR ASR: {vm.get('rr_asr'):.4f}")
